-- Additive V2.3 closure tables; safe to run repeatedly after the base schema.
-- Manual bank remittance result fields are additive so existing withdrawals and
-- the generic WeChat channel callback remain backward compatible.
SET @hx_withdrawal_payout_operator = (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='hx_withdrawal' AND column_name='payout_operator');
SET @hx_withdrawal_payout_evidence = (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='hx_withdrawal' AND column_name='payout_evidence_json');
SET @hx_withdrawal_payout_reason = (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='hx_withdrawal' AND column_name='payout_reason');
SET @hx_withdrawal_payout_recorded = (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='hx_withdrawal' AND column_name='payout_recorded_at');
SET @hx_withdrawal_out_bill = (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='hx_withdrawal' AND column_name='provider_out_bill_no');
SET @hx_withdrawal_bill = (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='hx_withdrawal' AND column_name='provider_bill_no');
SET @hx_withdrawal_state = (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='hx_withdrawal' AND column_name='provider_state');
SET @hx_withdrawal_package = (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='hx_withdrawal' AND column_name='provider_package');
SET @hx_withdrawal_updated = (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='hx_withdrawal' AND column_name='provider_updated_at');
SET @hx_withdrawal_sql = IF(@hx_withdrawal_payout_operator=0,'ALTER TABLE hx_withdrawal ADD COLUMN payout_operator BIGINT', 'SELECT 1'); PREPARE hx_withdrawal_stmt FROM @hx_withdrawal_sql; EXECUTE hx_withdrawal_stmt; DEALLOCATE PREPARE hx_withdrawal_stmt;
SET @hx_withdrawal_sql = IF(@hx_withdrawal_payout_evidence=0,'ALTER TABLE hx_withdrawal ADD COLUMN payout_evidence_json TEXT', 'SELECT 1'); PREPARE hx_withdrawal_stmt FROM @hx_withdrawal_sql; EXECUTE hx_withdrawal_stmt; DEALLOCATE PREPARE hx_withdrawal_stmt;
SET @hx_withdrawal_sql = IF(@hx_withdrawal_payout_reason=0,'ALTER TABLE hx_withdrawal ADD COLUMN payout_reason VARCHAR(500)', 'SELECT 1'); PREPARE hx_withdrawal_stmt FROM @hx_withdrawal_sql; EXECUTE hx_withdrawal_stmt; DEALLOCATE PREPARE hx_withdrawal_stmt;
SET @hx_withdrawal_sql = IF(@hx_withdrawal_payout_recorded=0,'ALTER TABLE hx_withdrawal ADD COLUMN payout_recorded_at TIMESTAMP NULL', 'SELECT 1'); PREPARE hx_withdrawal_stmt FROM @hx_withdrawal_sql; EXECUTE hx_withdrawal_stmt; DEALLOCATE PREPARE hx_withdrawal_stmt;
SET @hx_withdrawal_sql = IF(@hx_withdrawal_out_bill=0,'ALTER TABLE hx_withdrawal ADD COLUMN provider_out_bill_no VARCHAR(32)', 'SELECT 1'); PREPARE hx_withdrawal_stmt FROM @hx_withdrawal_sql; EXECUTE hx_withdrawal_stmt; DEALLOCATE PREPARE hx_withdrawal_stmt;
SET @hx_withdrawal_sql = IF(@hx_withdrawal_bill=0,'ALTER TABLE hx_withdrawal ADD COLUMN provider_bill_no VARCHAR(64)', 'SELECT 1'); PREPARE hx_withdrawal_stmt FROM @hx_withdrawal_sql; EXECUTE hx_withdrawal_stmt; DEALLOCATE PREPARE hx_withdrawal_stmt;
SET @hx_withdrawal_sql = IF(@hx_withdrawal_state=0,'ALTER TABLE hx_withdrawal ADD COLUMN provider_state VARCHAR(32)', 'SELECT 1'); PREPARE hx_withdrawal_stmt FROM @hx_withdrawal_sql; EXECUTE hx_withdrawal_stmt; DEALLOCATE PREPARE hx_withdrawal_stmt;
SET @hx_withdrawal_sql = IF(@hx_withdrawal_package=0,'ALTER TABLE hx_withdrawal ADD COLUMN provider_package TEXT', 'SELECT 1'); PREPARE hx_withdrawal_stmt FROM @hx_withdrawal_sql; EXECUTE hx_withdrawal_stmt; DEALLOCATE PREPARE hx_withdrawal_stmt;
SET @hx_withdrawal_sql = IF(@hx_withdrawal_updated=0,'ALTER TABLE hx_withdrawal ADD COLUMN provider_updated_at TIMESTAMP NULL', 'SELECT 1'); PREPARE hx_withdrawal_stmt FROM @hx_withdrawal_sql; EXECUTE hx_withdrawal_stmt; DEALLOCATE PREPARE hx_withdrawal_stmt;
SET @hx_onboarding_transfer_ref = (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='hx_merchant_onboarding' AND column_name='transfer_auth_ref');
SET @hx_onboarding_transfer_status = (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='hx_merchant_onboarding' AND column_name='transfer_auth_status');
SET @hx_onboarding_transfer_at = (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='hx_merchant_onboarding' AND column_name='transfer_auth_at');
SET @hx_onboarding_sql = IF(@hx_onboarding_transfer_ref=0,'ALTER TABLE hx_merchant_onboarding ADD COLUMN transfer_auth_ref VARCHAR(100)', 'SELECT 1'); PREPARE hx_onboarding_stmt FROM @hx_onboarding_sql; EXECUTE hx_onboarding_stmt; DEALLOCATE PREPARE hx_onboarding_stmt;
SET @hx_onboarding_sql = IF(@hx_onboarding_transfer_status=0,'ALTER TABLE hx_merchant_onboarding ADD COLUMN transfer_auth_status VARCHAR(24) NOT NULL DEFAULT ''NOT_SUBMITTED''', 'SELECT 1'); PREPARE hx_onboarding_stmt FROM @hx_onboarding_sql; EXECUTE hx_onboarding_stmt; DEALLOCATE PREPARE hx_onboarding_stmt;
SET @hx_onboarding_sql = IF(@hx_onboarding_transfer_at=0,'ALTER TABLE hx_merchant_onboarding ADD COLUMN transfer_auth_at TIMESTAMP NULL', 'SELECT 1'); PREPARE hx_onboarding_stmt FROM @hx_onboarding_sql; EXECUTE hx_onboarding_stmt; DEALLOCATE PREPARE hx_onboarding_stmt;
UPDATE hx_merchant_onboarding SET transfer_auth_status='PENDING' WHERE authorization_status='VERIFIED' AND transfer_auth_status='NOT_SUBMITTED';
CREATE TABLE IF NOT EXISTS hx_merchant_onboarding (shop_id BIGINT PRIMARY KEY, subject_type VARCHAR(24), subject_name VARCHAR(160), legal_representative VARCHAR(80), license_no VARCHAR(32), contact_phone VARCHAR(32), settlement_bank VARCHAR(120), settlement_account_ref VARCHAR(128), attachment_ids TEXT, application_ref VARCHAR(100), application_status VARCHAR(24) NOT NULL DEFAULT 'NOT_SUBMITTED', authorization_ref VARCHAR(100), authorization_status VARCHAR(24) NOT NULL DEFAULT 'NOT_SUBMITTED', app_id VARCHAR(80), merchant_no VARCHAR(80), certificate_ref VARCHAR(100), certificate_status VARCHAR(24) NOT NULL DEFAULT 'NOT_SUBMITTED', certificate_serial VARCHAR(100), expires_at DATE, contracted_fee_bps INT, settlement_days INT, abnormal_reason VARCHAR(500), rejection_reason VARCHAR(500), updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS hx_policy (id VARCHAR(64) PRIMARY KEY, shop_id BIGINT NOT NULL, policy_type VARCHAR(40) NOT NULL, version VARCHAR(40) NOT NULL, title VARCHAR(160) NOT NULL, content TEXT NOT NULL, status VARCHAR(20) NOT NULL, published_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(shop_id,policy_type,version));
CREATE TABLE IF NOT EXISTS hx_policy_consent (member_id BIGINT NOT NULL, shop_id BIGINT NOT NULL, policy_type VARCHAR(40) NOT NULL, version VARCHAR(40) NOT NULL, source VARCHAR(32) NOT NULL, consented_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(member_id,shop_id,policy_type,version));
CREATE TABLE IF NOT EXISTS hx_pick_task (order_id VARCHAR(64) PRIMARY KEY, shop_id BIGINT NOT NULL, status VARCHAR(24) NOT NULL, started_by BIGINT, started_at TIMESTAMP NULL, completed_by BIGINT, completed_at TIMESTAMP NULL);
CREATE TABLE IF NOT EXISTS hx_direct_sale_aftersale (id VARCHAR(64) PRIMARY KEY, shop_id BIGINT NOT NULL, customer_refund_id VARCHAR(64) NOT NULL UNIQUE, wholesale_order_id VARCHAR(64) NOT NULL, wholesale_refund_id VARCHAR(64), sku_id VARCHAR(64) NOT NULL, qty INT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);

